    v_plasma: f64,
    q_liver: f64,
    q_gut: f64,
    q_kidney: f64,
    q_lung: f64,
    q_heart: f64,
    q_brain: f64,
    q_muscle: f64,
    q_skin: f64,
    q_fat: f64,
    q_spleen: f64,
    q_bone: f64,
    q_rest: f64,
    v_liver: f64,
    v_gut: f64,
    v_kidney: f64,
    v_lung: f64,
    v_heart: f64,
    v_brain: f64,
    v_muscle: f64,
    v_skin: f64,
    v_fat: f64,
    v_spleen: f64,
    v_bone: f64,
    v_rest: f64,
    kp_liver: f64,
    kp_gut: f64,
    kp_kidney: f64,
    kp_lung: f64,
    kp_heart: f64,
    kp_brain: f64,
    kp_muscle: f64,
    kp_skin: f64,
    kp_fat: f64,
    kp_spleen: f64,
    kp_bone: f64,
    kp_rest: f64,
    cl_hep: f64,
    cl_renal: f64,
