    let p = Epistemic::measured(10.0, 0.0)
    let q = Epistemic::measured(13.0, 0.0)
    if approx(ep_distance(&p, &q), 3.0) { print("certain corner W2=|dmean|=3: PASS") }
    else { print("certain: FAIL"); ok = false }

