    assert_true(zd_count < 5, "most embeddings should not be zero divisors")

    let zd_loss = entity_zero_divisor_loss(kg_cayley)
    assert_true(zd_loss >= 0.0, "ZD loss should be non-negative")
    println("  PASS")

    // ---- Test 6: Backward pass ----
    println("T08: Backward pass (Cayley score)")
