    let r = relation_embedding_raw(kg_cayley, 0)
    let t = entity_embedding_raw(kg_cayley, 1)

    let grads_cayley = sed_cayley_score_backward(1.0, h, r, t)
    let gh_norm = sed_norm(grads_cayley.grad_h)
    let gr_norm = sed_norm(grads_cayley.grad_r)
    let gt_norm = sed_norm(grads_cayley.grad_t)
    assert_true(gh_norm > 0.0, "head gradient should be non-zero")
    assert_true(gr_norm > 0.0, "relation gradient should be non-zero")
    assert_true(gt_norm > 0.0, "tail gradient should be non-zero")

