fn main() -> i32 with IO, Mut, Div, Panic {
    var fails = 0
    var nu = matnm_new(6 as i64, 5 as i64)
    nu = matnm_set(nu, 0 as i64, 0 as i64, 0.0 - 1.0)   // R0: H2 + CO2 -> CH4
    nu = matnm_set(nu, 1 as i64, 0 as i64, 1.0)
    nu = matnm_set(nu, 5 as i64, 0 as i64, 0.0 - 1.0)
    nu = matnm_set(nu, 2 as i64, 1 as i64, 0.0 - 1.0)   // R1: acid channel
