    nu = matnm_set(nu, 4 as i64, 1 as i64, 1.0)
    nu = matnm_set(nu, 2 as i64, 2 as i64, 0.0 - 1.0)   // R2: CO2 channel
    nu = matnm_set(nu, 5 as i64, 2 as i64, 0.0 - 1.0)
    nu = matnm_set(nu, 3 as i64, 2 as i64, 1.0)
    nu = matnm_set(nu, 4 as i64, 2 as i64, 2.0)
    nu = matnm_set(nu, 2 as i64, 3 as i64, 0.0 - 1.0)   // R3: water channel
    nu = matnm_set(nu, 3 as i64, 3 as i64, 1.0)
    nu = matnm_set(nu, 4 as i64, 3 as i64, 1.0)
    nu = matnm_set(nu, 3 as i64, 4 as i64, 0.0 - 1.0)   // R4: closure
    nu = matnm_set(nu, 4 as i64, 4 as i64, 0.0 - 1.0)
